/// contract for get privilege info
/// </summary>
[DataContract]
class NDXPrivilegeInfoContract
    extends SysOperationDataContractBase
    implements SysOperationValidatable
{
    boolean getPrivilegeInfo;

}

Method.Source:
[DataMember]
public boolean parmGetPrivilegeInfo(boolean _getPrivilegeInfo = getPrivilegeInfo)
{
    getPrivilegeInfo = _getPrivilegeInfo;
    return getPrivilegeInfo;
}
